export interface Row {
  id: string;
  auth: string;
  cite: string;
  requirement: string;
  /** Verbatim source text. Empty only when `identifierOnly` (copyrighted standard recorded by identifier). */
  quote: string;
  evidence: string;
  cadence: Cadence[];
  frequency: string;
  owner: string;
  kitchen?: boolean;
  should?: boolean;
  /** Designated "recommended" by the standard itself. */
  recommended?: boolean;
  identifierOnly?: boolean;
}

